<script setup>
import { useOpenSong } from '../../api/openSong.js'
const openSong = useOpenSong()
import { getLvmdfMap } from '../../api/lvmdf.js'
import lvmdfCard from '../../components/cards/lvmdfCard.vue'
import ScrollTabs from '../../components/ui/ScrollTabs.vue'
import { ref, onMounted, computed, onUnmounted } from 'vue'
import { useRemScale } from '../../utils/rem.js'

import { useRouter } from 'vue-router'

useRemScale()

const router = useRouter()
const songlvmdf = ref({})

// 标签顺序就是版本时间顺序，最后一个是最新版，进页面默认选中它
const versions = [
  '1.2.0', '1.3.0', '1.4.0', '1.4.2', '1.4.4', '1.5.0', '1.6.0', '1.6.5', '1.6.8',
  '2.0.0', '2.5.0', '2.5.1',
  '3.2.0', '3.5.0', '3.9.0', '3.10.2', '3.11.0', '3.12.0', '3.15.1', '3.18.3', '3.18.4', '3.20.0',
  '4.0.1', '4.0.1.1',
]

const selectedVersion = ref(versions[versions.length - 1])

// 版本栏最右侧钉一个「总览」：把 24 个版本的变更一次性摊开看
const OVERVIEW = '__overview__'
const pinnedTab = { value: OVERVIEW, label: '总览' }

const DIFF_ORDER = ['EZ', 'HD', 'IN', 'AT', 'Legacy']

const isOverview = computed(() => selectedVersion.value === OVERVIEW)
const overviewData = ref({})
const overviewLoading = ref(false)

const commonConfig = {
  color: '#212426',
  text: '#ffffff'
}

const versionConfig = Object.fromEntries(
  versions.map((version) => [version, { file: `/files/lvmdf/lvmdf${version}.json` }])
)

const mainColor = computed(() => commonConfig.color)
const textColor = computed(() => commonConfig.text)

const fetchSongData = async () => {
  if (isOverview.value) return
  const filePath = versionConfig[selectedVersion.value].file
  const data = await getLvmdfMap(filePath)
  songlvmdf.value = data
}

// 总览要把每个版本的文件都读一遍，切过去时才加载，读完缓存住
const loadOverview = async () => {
  if (Object.keys(overviewData.value).length || overviewLoading.value) return
  overviewLoading.value = true
  try {
    const pairs = await Promise.all(
      versions.map(async (version) => [version, await getLvmdfMap(versionConfig[version].file)])
    )
    overviewData.value = Object.fromEntries(pairs)
  } finally {
    overviewLoading.value = false
  }
}

// 总览是历史变更汇总：一首曲目一张卡，把各难度历次改动的定数连成一条链，不按版本拆开
const overviewSongs = computed(() => {
  const bySong = new Map()
  for (const version of versions) {
    const songs = overviewData.value[version] || {}
    for (const [key, song] of Object.entries(songs)) {
      if (!bySong.has(key)) bySong.set(key, { key, name: song.songName, cover: '', chains: new Map() })
      const entry = bySong.get(key)
      entry.cover = song.cover || entry.cover
      for (const diff of DIFF_ORDER) {
        const cell = song[diff]
        if (!cell) continue
        const old = Number(cell.old)
        const next = Number(cell.new)
        // 老定数 = 新定数 的格子不是一次变更，跳过
        if (old === next) continue
        if (!entry.chains.has(diff)) {
          entry.chains.set(diff, { name: diff, color: cell.color, values: [old] })
        }
        const chain = entry.chains.get(diff)
        // 接上一次改完的值，跨版本的连续改动就串成一条链
        if (chain.values[chain.values.length - 1] !== old) chain.values.push(old)
        chain.values.push(next)
      }
    }
  }
  return [...bySong.values()]
    .filter((entry) => entry.chains.size)
    .map((entry) => ({
      key: entry.key,
      name: entry.name,
      cover: entry.cover,
      // 难度列按 EZ / HD / IN / AT / Legacy 固定顺序摆，不跟首次改动的先后
      chains: [...entry.chains.values()].sort(
        (a, b) => DIFF_ORDER.indexOf(a.name) - DIFF_ORDER.indexOf(b.name)
      )
    }))
    .sort((a, b) => a.name.localeCompare(b.name, 'zh-Hans-CN'))
})

// 一条链首尾相减就是这段时间的净变化，和定数变更卡一样标出涨跌
const deltaOf = (chain) => Number(chain.values[chain.values.length - 1]) - Number(chain.values[0])

const deltaText = (chain) => {
  const delta = deltaOf(chain)
  return delta > 0 ? `+${delta.toFixed(1)}` : delta.toFixed(1)
}

const deltaClass = (chain) => {
  const delta = deltaOf(chain)
  if (delta > 0) return 'is-up'
  if (delta < 0) return 'is-down'
  return 'is-flat'
}

const changeVersion = async (version) => {
  selectedVersion.value = version
  if (version === OVERVIEW) {
    await loadOverview()
    return
  }
  fetchSongData()
}

onMounted(async () => {
  await fetchSongData()
})


const goToTable = (tableName) => {
  router.push({ name: tableName })
}

const handleLink = (link) => {
  if (link.startsWith('/') || !link.includes('http')) {
    goToTable(link)
  } else {
    window.open(link, '_blank')
  }
}
</script>

<template>
  <div class="dt-page">

    <ScrollTabs
      :model-value="selectedVersion"
      :items="versions"
      :pinned="pinnedTab"
      class="version-tabs"
      sticky
      aria-label="选择版本"
      @update:model-value="changeVersion"
    />

    <!-- 总览：历史变更汇总，一首曲目一张卡，各难度的定数变化连成一条链 -->
    <div v-if="isOverview" class="overview">
      <div class="card-grid">
        <article
          v-for="item in overviewSongs"
          :key="item.key"
          class="overview-card"
          :title="item.name"
          @click="openSong(item.key)"
        >
          <h2 class="overview-name">{{ item.name }}</h2>
          <div class="overview-cover">
            <img :src="item.cover" :alt="item.name" class="overview-cover-img" loading="lazy" />
          </div>
          <div class="overview-chains">
            <div v-for="chain in item.chains" :key="chain.name" class="overview-chain">
              <span class="overview-diff" :style="{ backgroundColor: chain.color }">
                {{ chain.name }}
              </span>
              <span class="overview-values">
                <template v-for="(value, index) in chain.values" :key="index">
                  <span v-if="index" class="overview-arrow" aria-hidden="true">↓</span>
                  <span
                    class="dt-num overview-value"
                    :class="{ 'overview-latest': index === chain.values.length - 1 }"
                  >
                    {{ value.toFixed(1) }}
                  </span>
                </template>
                <span class="overview-delta" :class="deltaClass(chain)">{{ deltaText(chain) }}</span>
              </span>
            </div>
          </div>
        </article>
      </div>
      <div v-if="overviewLoading" class="dt-empty">正在汇总各版本…</div>
      <div v-else-if="!overviewSongs.length" class="dt-empty">还没有定数变更记录</div>
    </div>

    <div v-else class="card-grid">
      <lvmdf-card
        v-for="(songItem, songKey) in songlvmdf"
        :key="songKey"
        :song-data="songItem"
        :song-key="songKey" @click="openSong(songKey)"
        :main-color="mainColor"
        :text-color="textColor"
      />
    </div>

    <div v-if="!isOverview && !Object.keys(songlvmdf).length" class="dt-empty">
      该版本没有定数变更记录
    </div>
  </div>
</template>

